     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="UTF-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
     6	<title>TERMINAL HORIZON — THREE SIMULATION SUITE</title>
     7	<style>
     8	@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Inconsolata:wght@300;400;600&display=swap');
     9	:root {
    10	  --bg:#03040a; --panel:#070810; --border:#12142a; --border-bright:#1e2245;
    11	  --cascade:#ff2200; --winter:#00aaff; --pop-surface:#ff6600; --pop-prepared:#00ff88;
    12	  --braided:#00ffcc; --nonbraided:#ff4466; --gold:#d4a843;
    13	  --text:#b8bcd4; --dim:#444466; --bright:#e8ecff;
    14	  --glow-red:0 0 20px rgba(255,34,0,0.5); --glow-blue:0 0 20px rgba(0,170,255,0.5);
    15	  --glow-green:0 0 20px rgba(0,255,136,0.5); --glow-teal:0 0 20px rgba(0,255,204,0.5);
    16	  --glow-pink:0 0 20px rgba(255,68,102,0.5); --glow-gold:0 0 20px rgba(212,168,67,0.4);
    17	}
    18	*{margin:0;padding:0;box-sizing:border-box;}
    19	html{font-size:16px;}
    20	body{background:var(--bg);color:var(--text);font-family:'Inconsolata',monospace;min-height:100vh;overflow-x:hidden;-webkit-text-size-adjust:100%;}
    21	body::before{content:'';position:fixed;inset:0;background:radial-gradient(ellipse 60% 40% at 20% 20%,rgba(255,34,0,0.03) 0%,transparent 70%),radial-gradient(ellipse 50% 30% at 80% 80%,rgba(0,170,255,0.03) 0%,transparent 70%),radial-gradient(ellipse 40% 60% at 50% 50%,rgba(0,255,204,0.02) 0%,transparent 70%);pointer-events:none;z-index:0;}
    22	.scanlines{position:fixed;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,0,0,0.05) 3px,rgba(0,0,0,0.05) 4px);pointer-events:none;z-index:1000;}
    23	.wrapper{position:relative;z-index:1;}
    24	header{padding:16px 16px 14px;border-bottom:1px solid var(--border-bright);position:relative;overflow:hidden;}
    25	header::after{content:'';position:absolute;bottom:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent 0%,var(--cascade) 30%,var(--braided) 70%,transparent 100%);opacity:0.5;}
    26	.hdr{display:flex;flex-direction:column;gap:8px;}
    27	@media(min-width:900px){.hdr{flex-direction:row;justify-content:space-between;align-items:start;} header{padding:24px 40px 18px;}}
    28	h1{font-family:'Orbitron',monospace;font-weight:900;font-size:clamp(16px,5vw,32px);letter-spacing:clamp(1px,0.5vw,4px);color:var(--bright);line-height:1.1;}
    29	h1 em{color:var(--cascade);font-style:normal;text-shadow:var(--glow-red);}
    30	h1 span{color:var(--braided);text-shadow:var(--glow-teal);}
    31	.subtitle{font-size:clamp(8px,2vw,9px);letter-spacing:1.5px;color:var(--dim);text-transform:uppercase;margin-top:3px;line-height:1.5;}
    32	.hdr-meta{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:9px;color:var(--dim);}
    33	.hdr-meta .live{color:var(--cascade);animation:pulse 1.6s infinite;}
    34	.hdr-meta .author{color:var(--gold);letter-spacing:1.5px;}
    35	@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.2}}
    36	.tab-nav{display:flex;border-bottom:1px solid var(--border-bright);background:rgba(0,0,0,0.3);overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;}
    37	.tab-nav::-webkit-scrollbar{display:none;}
    38	.tab{flex-shrink:0;padding:12px 14px;font-family:'Orbitron',monospace;font-size:clamp(8px,2vw,9px);font-weight:700;letter-spacing:1.5px;color:var(--dim);cursor:pointer;border-bottom:2px solid transparent;transition:all 0.2s;text-transform:uppercase;white-space:nowrap;-webkit-tap-highlight-color:transparent;position:relative;}
    39	.tab:hover{color:var(--text);}
    40	.tab.active{color:var(--bright);border-bottom-color:var(--gold);}
    41	.tab.active::after{content:'';position:absolute;bottom:-2px;left:0;right:0;height:2px;background:var(--gold);box-shadow:var(--glow-gold);}
    42	.sim-panel{display:none;padding:12px 12px 32px;}
    43	.sim-panel.active{display:block;}
    44	@media(min-width:900px){.sim-panel{padding:20px 40px 40px;}}
    45	.sim-layout{display:flex;flex-direction:column;gap:14px;}
    46	@media(min-width:900px){.sim-layout{display:grid;grid-template-columns:1fr 300px;gap:22px;height:calc(100vh - 190px);min-height:520px;}}
    47	.chart-col{display:flex;flex-direction:column;gap:10px;}
    48	.chart-label{font-family:'Orbitron',monospace;font-size:clamp(8px,2vw,9px);letter-spacing:1.5px;color:var(--dim);text-transform:uppercase;line-height:1.4;}
    49	.chart-scroll{width:100%;overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;scrollbar-width:thin;scrollbar-color:var(--border-bright) transparent;}
    50	.chart-scroll::-webkit-scrollbar{height:3px;}
    51	.chart-scroll::-webkit-scrollbar-thumb{background:var(--border-bright);}
    52	.chart-wrap{position:relative;width:620px;min-width:620px;height:260px;}
    53	@media(min-width:900px){.chart-scroll{overflow-x:visible;}.chart-wrap{width:100%;min-width:0;flex:1;height:auto;min-height:300px;}}
    54	canvas{display:block;width:100%;height:100%;}
    55	.swipe-hint{font-size:9px;color:var(--dim);letter-spacing:2px;text-align:center;padding:3px 0;opacity:0.5;}
    56	@media(min-width:900px){.swipe-hint{display:none;}}
    57	.view-btns{display:flex;gap:5px;flex-wrap:wrap;}
    58	.sidebar-col{display:flex;flex-direction:column;gap:12px;}
    59	@media(min-width:900px){.sidebar-col{overflow-y:auto;}}
    60	.panel{background:var(--panel);border:1px solid var(--border);padding:12px;position:relative;}
    61	.panel::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border-bright),transparent);}
    62	.panel-title{font-family:'Orbitron',monospace;font-size:clamp(8px,2vw,9px);letter-spacing:2px;color:var(--dim);text-transform:uppercase;margin-bottom:10px;padding-bottom:7px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;cursor:pointer;-webkit-tap-highlight-color:transparent;user-select:none;}
    63	.panel-title::after{content:'▾';font-size:10px;color:var(--dim);transition:transform 0.2s;}
    64	.panel.collapsed .panel-title::after{transform:rotate(-90deg);}
    65	.panel-body{overflow:hidden;}
    66	.panel.collapsed .panel-body{max-height:0!important;}
    67	.ctrl{margin-bottom:12px;}
    68	.ctrl-label{font-size:9px;color:var(--dim);letter-spacing:1px;display:flex;justify-content:space-between;margin-bottom:7px;}
    69	.ctrl-label span{color:var(--text);font-size:10px;}
    70	input[type=range]{-webkit-appearance:none;width:100%;height:4px;background:var(--border-bright);outline:none;border-radius:2px;cursor:pointer;}
    71	input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px;background:var(--gold);cursor:pointer;border-radius:2px;box-shadow:0 0 8px rgba(212,168,67,0.5);}
    72	.metrics{display:grid;grid-template-columns:1fr 1fr;gap:6px;}
    73	.metric{background:rgba(255,255,255,0.02);border:1px solid var(--border);padding:8px 10px;}
    74	.metric-label{font-size:8px;color:var(--dim);letter-spacing:0.5px;text-transform:uppercase;margin-bottom:3px;line-height:1.3;}
    75	.metric-value{font-family:'Orbitron',monospace;font-size:clamp(12px,3.5vw,14px);font-weight:700;}
    76	.mv-red{color:var(--cascade);text-shadow:var(--glow-red);}
    77	.mv-blue{color:var(--winter);text-shadow:var(--glow-blue);}
    78	.mv-green{color:var(--pop-prepared);text-shadow:var(--glow-green);}
    79	.mv-teal{color:var(--braided);text-shadow:var(--glow-teal);}
    80	.mv-pink{color:var(--nonbraided);text-shadow:var(--glow-pink);}
    81	.mv-gold{color:var(--gold);text-shadow:var(--glow-gold);}
    82	.mv-orange{color:var(--pop-surface);}
    83	.legend-grid{display:grid;grid-template-columns:1fr 1fr;gap:4px 10px;}
    84	@media(min-width:900px){.legend-grid{grid-template-columns:1fr;}}
    85	.legend-item{display:flex;align-items:center;gap:8px;font-size:clamp(9px,2.2vw,10px);margin-bottom:2px;}
    86	.leg-line{width:20px;height:2px;flex-shrink:0;}
    87	.leg-dash{width:20px;height:0;flex-shrink:0;border-top:2px dashed currentColor;}
    88	.event-log{font-size:clamp(9px,2vw,9px);line-height:1.9;max-height:150px;overflow-y:auto;}
    89	.ev{padding:2px 0;border-bottom:1px solid rgba(255,255,255,0.03);}
    90	.ev.crit{color:var(--cascade);} .ev.warn{color:var(--gold);} .ev.info{color:var(--winter);}
    91	.ev.good{color:var(--pop-prepared);} .ev.teal{color:var(--braided);} .ev.pink{color:var(--nonbraided);}
    92	.verdict{background:rgba(212,168,67,0.04);border:1px solid rgba(212,168,67,0.15);padding:12px;font-size:clamp(9px,2vw,10px);line-height:1.8;}
    93	.verdict.nb{background:rgba(255,68,102,0.04);border-color:rgba(255,68,102,0.2);}
    94	.verdict.br{background:rgba(0,255,204,0.04);border-color:rgba(0,255,204,0.2);}
    95	.v-label{font-family:'Orbitron',monospace;font-size:clamp(8px,1.8vw,9px);letter-spacing:2px;text-transform:uppercase;margin-bottom:6px;}
    96	.v-label.nb{color:var(--nonbraided);}
    97	.v-label.br{color:var(--braided);}
    98	.v-label.gold{color:var(--gold);}
    99	.btn{background:transparent;border:1px solid var(--border-bright);color:var(--dim);font-family:'Inconsolata',monospace;font-size:clamp(9px,2vw,10px);letter-spacing:1.5px;padding:8px 10px;cursor:pointer;text-transform:uppercase;transition:all 0.15s;-webkit-tap-highlight-color:transparent;touch-action:manipulation;}
   100	.btn:hover,.btn:active{border-color:var(--gold);color:var(--gold);}
   101	.btn.active{border-color:var(--gold);color:var(--gold);background:rgba(212,168,67,0.08);}
   102	.age-bar-wrap{margin-top:8px;}
   103	.age-bar-label{font-size:8px;color:var(--dim);letter-spacing:1px;margin-bottom:4px;}
   104	.age-bar{height:8px;background:var(--border);border-radius:2px;overflow:hidden;margin-bottom:3px;}
   105	.age-fill-nb{height:100%;background:linear-gradient(90deg,var(--nonbraided),rgba(255,68,102,0.3));transition:width 0.3s;}
