   672	function br_civIndex(yr){
   673	  if(yr<BR_START)return 0.88;
   674	  const t=yr-BR_START;
   675	  const braid=br_braidPropagation(yr);
   676	  const fp=br_founderPresence(yr);
   677	  const cog=br_cogDiversity(yr);
   678	  // Knowledge compounds upward: founders accumulate experience, no generational reset
   679	  const compound=1+Math.log1p(t/25)*(S3.telo/100)*0.5;
   680	  return clamp(0.88*fp*braid*cog*compound,0,2.0); // can exceed 1.0
   681	}
   682	
   683	function s3param(k,v){S3[k]=parseFloat(v);const f={pop:v=>`${v}M`,telo:v=>`${v}%`,germ:v=>`${v}%`,adopt:v=>`${v}%`};if(f[k])document.getElementById('v3_'+k).textContent=f[k](v);drawSim3();}
   684	function s3view(v){S3.view=v;['all','civ','bio','cog','braid'].forEach(x=>document.getElementById('s3_'+x).classList.remove('active'));document.getElementById('s3_'+v).classList.add('active');drawSim3();}
   685	
   686	function drawSim3(){
   687	  const cv=document.getElementById('c3');
   688	  const{w:W,h:H,ctx}=resizeCanvas(cv);
   689	  const pad={t:24,r:24,b:50,l:56};
   690	  const cW=W-pad.l-pad.r,cH=H-pad.t-pad.b;
   691	  ctx.clearRect(0,0,W,H);ctx.fillStyle='#03040a';ctx.fillRect(0,0,W,H);
   692	  drawGridLines(ctx,W,H,pad,12,10);
   693	  drawBorder(ctx,W,H,pad);
   694	  const toX=yr=>pad.l+((yr-BR_START)/BR_SPAN)*cW;
   695	  const toY=v=>pad.t+(1-clamp(v/2.0,0,1))*cH; // scaled 0-200% to show post-human
   696	  ctx.fillStyle='rgba(255,255,255,0.25)';ctx.font='9px Inconsolata';ctx.textAlign='center';
   697	  for(let yr=BR_START;yr<=BR_END;yr+=25)ctx.fillText(yr,toX(yr),pad.t+cH+16);
   698	  ctx.textAlign='right';for(let i=0;i<=10;i++)ctx.fillText(`${i*20}%`,pad.l-5,toY(i/10*2)+3);
   699	  ctx.save();ctx.translate(12,pad.t+cH/2);ctx.rotate(-Math.PI/2);ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='8px Inconsolata';ctx.fillText('INDEX (>100% = POST-HUMAN THRESHOLD)',0,0);ctx.restore();
   700	  ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='8px Inconsolata';ctx.fillText('CALENDAR YEAR (POST-EMERGENCE)',pad.l+cW/2,H-8);
   701	  // 100% baseline
   702	  const base100=toY(1.0);
   703	  ctx.save();ctx.strokeStyle='rgba(255,255,255,0.1)';ctx.lineWidth=1;ctx.setLineDash([2,6]);
   704	  ctx.beginPath();ctx.moveTo(pad.l,base100);ctx.lineTo(pad.l+cW,base100);ctx.stroke();ctx.setLineDash([]);ctx.restore();
   705	  ctx.fillStyle='rgba(255,255,255,0.25)';ctx.font='8px Inconsolata';ctx.textAlign='right';
   706	  ctx.fillText('PRE-EVENT HUMAN BASELINE 100%',pad.l+cW-4,base100-3);
   707	  const STEPS=300;
   708	  const pts=fn=>{const a=[];for(let i=0;i<=STEPS;i++){const yr=BR_START+i*(BR_SPAN/STEPS);a.push([toX(yr),toY(fn(yr))]);}return a;};
   709	  const sv=S3.view;
   710	  // Braiding propagation
   711	  if(sv==='all'||sv==='braid'){const bp=pts(yr=>br_braidPropagation(yr)*1.5);drawArea(ctx,bp,'rgb(212,168,67)',0.04,H,pad);drawCurve(ctx,bp,'rgb(212,168,67)','rgb(212,168,67)',2);}
   712	  // Cognitive diversity
   713	  if(sv==='all'||sv==='cog'){const cd=pts(yr=>br_cogDiversity(yr)*1.5);drawArea(ctx,cd,'rgb(150,150,255)',0.04,H,pad);drawCurve(ctx,cd,'rgba(150,150,255,0.7)',null,1.5,[3,4]);}
   714	  // Biological rejuvenation index (how far from entry age they are)
   715	  if(sv==='all'||sv==='bio'){
   716	    const bi=pts(yr=>{const age=br_bioAge(yr);return clamp((80-age)/60,0,1)*1.5;});
   717	    drawArea(ctx,bi,'rgb(0,255,136)',0.05,H,pad);drawCurve(ctx,bi,'rgb(0,255,136)',null,2,[2,4]);
   718	  }
   719	  // Civilizational index
   720	  if(sv==='all'||sv==='civ'){const ci=pts(yr=>br_civIndex(yr));drawArea(ctx,ci,'rgb(0,255,204)',0.08,H,pad);drawCurve(ctx,ci,'rgb(0,255,204)','rgb(0,255,204)',3);}
   721	  // Metrics
   722	  const civ300=(br_civIndex(BR_END)*100).toFixed(0);
   723	  const cog300=(br_cogDiversity(BR_END)*100).toFixed(0);
   724	  const bioAge2152=br_bioAge(BR_START).toFixed(0);
   725	  const teloEff=S3.telo/100;
   726	  const effLife=Math.round(80+teloEff*500);
   727	  const bg1=(br_braidPropagation(BR_START+25)*100).toFixed(0);
   728	  const fpEnd=(br_founderPresence(BR_END)*100).toFixed(0);
   729	  document.getElementById('m3_bioage').textContent=`~${bioAge2152}yr`;
   730	  document.getElementById('m3_life').textContent=`${effLife}+yr`;
   731	  document.getElementById('m3_civ300').textContent=`${civ300}%`;
   732	  document.getElementById('m3_founders').textContent=`${fpEnd}%`;
   733	  document.getElementById('m3_bg1').textContent=`${bg1}%`;
   734	  document.getElementById('m3_cog300').textContent=`${cog300}%`;
   735	  document.getElementById('br_rejuv_bar').style.width=`${(S3.telo/100)*100}%`;
   736	  document.getElementById('br_rejuv_txt').textContent=`Age ~${bioAge2152} out (${S3.telo}% efficacy)`;
   737	  document.getElementById('s3_log').innerHTML=[
   738	    {c:'teal',t:`2041 — Founders enter bunkers. Braided mind installation begins.`},
   739	    {c:'teal',t:`2041-2152 — AI-directed cellular rejuvenation. 111yr reversal window.`},
   740	    {c:'teal',t:`2041-2152 — Telomere extension. Senescent cells cleared. DNA errors corrected.`},
   741	    {c:'good',t:`2152 — DOORS OPEN. Founders exit biologically age ~${bioAge2152}. Cognitive age 181yr.`},
   742	    {c:'teal',t:`2152 — Founders lead. Full institutional knowledge intact. No succession needed.`},
   743	    {c:'good',t:`${BR_START+25} — G1 born braided. ${bg1}% carry germline architecture.`},
   744	    {c:'teal',t:`${BR_START+75} — Founders at bio age ~${(20+(75*(1-teloEff*0.9))).toFixed(0)}. Still governing. G3 also braided.`},
   745	    {c:'teal',t:`2452 — Civ index: ${civ300}%. ${fpEnd}% founder presence. Post-human threshold crossed.`},
   746	  ].map(e=>`<div class="ev ${e.c}">${e.t}</div>`).join('');
   747	  document.getElementById('s3_verdict').innerHTML=`The person who made the decision walks out of the bunker in 2152 in the body of a <span style="color:var(--braided)">20-year-old</span> with <span style="color:var(--braided)">181 years of continuous memory</span>. No succession. No translation loss. No generation gap. G1 is born already braided. The civilizational index at 2452 is <span style="color:var(--braided)">${civ300}%</span> — <span style="color:var(--braided)">exceeding pre-event human baseline</span>. This is the first civilization in planetary history immune to its own succession problem. <strong>The founders are still there. They will always be there.</strong>`;
   748	}
