   751	// TAB SWITCHING
   752	// ═══════════════════════════════════════════
   753	function switchTab(n){
   754	  document.querySelectorAll('.tab').forEach((t,i)=>t.classList.toggle('active',i===n-1));
   755	  document.querySelectorAll('.sim-panel').forEach((p,i)=>p.classList.toggle('active',i===n-1));
   756	  if(n===1)drawSim1();
   757	  else if(n===2)drawSim2();
   758	  else drawSim3();
   759	}
